    expect(decodeClientFrame("not json{")).toBeNull();
    expect(decodeClientFrame(new Uint8Array([1, 2, 3]))).toBeNull();
    expect(decodeClientFrame(JSON.stringify({ t: "resync" }))).toMatchObject({ t: "resync" });
  });
});

