import type { InventorySlot } from "@/lib/game/types";

function makeState(slots: InventorySlot[], selectedSlot = 0): GameState & PlayerState {
  const state = {
    position: new THREE.Vector3(0, 64, 0),
    velocity: new THREE.Vector3(),
    yaw: 0,
    pitch: 0,
    onGround: true,
    inventory: slots,
    selectedSlot,
    mobs: [],
    timers: createTimers(),
    projectiles: [],
