1	import type { GameEngine } from "@/lib/game/engine/GameEngine";
2	import type { FrameInput, MoveIntents } from "@/lib/game/engine/state";
3	import {
4	  FLY_DOUBLE_TAP_WINDOW_SECONDS,
5	  TOUCH_HOLD_MINE_MS,
6	  TOUCH_JOYSTICK_DEADZONE,
7	  TOUCH_JOYSTICK_RADIUS_PX,
8	  TOUCH_LOOK_SENSITIVITY,
9	  TOUCH_SPRINT_DOUBLE_TAP_MS,
10	  TOUCH_TAP_MAX_MS,
11	  TOUCH_TAP_SLOP_PX
12	} from "@/lib/game/config";
13	import type { InputController } from "./inputController";
14	
15	/**
16	 * The touch counterpart of createInputController: same InputController
17	 * surface, but "gameplay capture" is a virtual `active` flag (there is no
18	 * pointer lock on touch — tap-to-play calls engage()). All gesture state
19	 * lives here, DOM-free: the TouchControls overlay forwards plain pointer
20	 * records into `controls`, so this whole state machine unit-tests without a
21	 * browser. The engine contract is identical to desktop: mutate FrameInput,
22	 * call engine.applyLook, dispatch Commands.
23	 *
24	 * Gesture model (Minecraft-PE classic): on the free look area, drag = look,
25	 * tap = one attack, press-and-hold within slop = attack + mineHeld until
26	 * lift — and a drag that leaves the slop first is ONLY ever a look (a camera
27	 * swipe must never dig). Movement rides a fixed-base joystick with 8-way
28	 * sectors; re-engaging the stick quickly latches sprint (applied only while
