    if (s.have >= s.need) continue;
    const hint = itemSourceHint(s.slotId);
    if (hint) lines.push(`→ ${labelFor(s.slotId)}: ${hint}`);
  }
  return { title: labelFor(recipe.result.slotId), lines };
}

