input.content:
/* --- On-screen touch controls (components/game/TouchControls.tsx) ---
   Layering: the look pad sits at z-index 3 — above the canvas/vignette (2),
   below the HUD (4) — so hotbar taps hit the hotbar while everything that
   falls through becomes look/mine input. Buttons and the joystick float at
   HUD level; panels (z 9) cover the lot, and the overlay unmounts anyway
   whenever one opens. */

.touch-lookpad {
  position: absolute;
  inset: 0;
  z-index: 3;
  touch-action: none;
}

.touch-joystick {
  position: absolute;
  left: calc(24px + var(--safe-l, 0px));
  bottom: calc(24px + var(--safe-b, 0px));
  z-index: 5;
  width: 144px;
  height: 144px;
  border-radius: 50%;
  border: 3px solid rgba(255, 255, 255, 0.35);
  background: rgba(10, 10, 14, 0.28);
  touch-action: none;
  user-select: none;
}

.touch-joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 56px;
  height: 56px;
  margin: -28px 0 0 -28px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.55);
  background: rgba(255, 255, 255, 0.28);
  pointer-events: none;
}

.touch-actions {
  position: absolute;
  right: calc(16px + var(--safe-r, 0px));
  bottom: calc(88px + var(--safe-b, 0px));
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}

.touch-topbar {
  position: absolute;
  top: calc(10px + var(--safe-t, 0px));
  left: calc(10px + var(--safe-l, 0px));
  z-index: 5;
  display: flex;
  gap: 8px;
}

.touch-btn {
  min-width: 58px;
  min-height: 46px;
  padding: 6px 12px;
  font-family: inherit;
  font-size: 13px;
  color: #fff;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.8);
  background: rgba(30, 30, 38, 0.55);
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-radius: 6px;
  touch-action: none;
  user-select: none;
}

.touch-btn:active,
.touch-btn.pressed {
  background: rgba(255, 255, 255, 0.3);
  border-color: rgba(255, 255, 255, 0.75);
}

.touch-btn-jump {
  min-width: 76px;
  min-height: 76px;
  border-radius: 50%;
}

/* The tap-to-play hint doubles as the engagement surface on touch. */
.touch-tap-area {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  font: inherit;
  color: inherit;
  touch-action: none;
}

