3	import { useEffect, useRef, useState } from "react";
4	import { TOUCH_JOYSTICK_RADIUS_PX } from "@/lib/game/config";
5	import type { TouchControlsApi } from "@/lib/game/input/touchInputController";
6	
7	/**
8	 * The on-screen touch controls: a fixed-base joystick (bottom-left), a
9	 * full-screen look pad behind the HUD (drag = look, tap = attack, hold =
10	 * mine), an action cluster (bottom-right), and a top bar (pause / inventory /
11	 * camera). Dumb by design — every gesture decision lives in the touch input
12	 * controller; this component only converts PointerEvents into plain
13	 * {pointerId, x, y} records (joystick coords relative to its center) and
14	 * renders the knob/pressed visuals. Handlers are pointerType-agnostic so a
15	 * mouse can drive the overlay (dev convenience + Playwright).
16	 */
17	
18	type TouchControlsProps = {
19	  controls: TouchControlsApi;
20	  /** Selected slot is edible/drinkable — show the Eat button. */
21	  showEat: boolean;
22	  /** Flying (Creative/Spectator): Jump/Sneak read as Rise/Descend. */
23	  isFlying: boolean;
24	  onPause: () => void;
25	  onOpenInventory: () => void;
26	  onToggleCamera: () => void;
27	  /** Unmount cleanup — drops held gestures so nothing sticks through a panel. */
28	  onDeactivate: () => void;
29	};
30	
31	/** setPointerCapture keeps drags delivering off-element; optional in happy-dom. */
32	function capture(e: React.PointerEvent): void {
33	  try {
34	    e.currentTarget.setPointerCapture(e.pointerId);
35	  } catch {
36	    // Test DOMs (and some odd UAs) lack pointer capture; drags just need the
37	    // finger to stay on-screen, which is the overwhelmingly common case.
38	  }
39	}
40	
41	export default function TouchControls({ controls, showEat, isFlying, onPause, onOpenInventory, onToggleCamera, onDeactivate }: TouchControlsProps) {
42	  // Visual knob offset (clamped); the controller does its own vector math.
43	  const [knob, setKnob] = useState({ x: 0, y: 0 });
44	  const [sneakOn, setSneakOn] = useState(controls.sneakLatched);
45	  const joystickCenter = useRef({ x: 0, y: 0 });
46	
47	  useEffect(() => () => onDeactivate(), [onDeactivate]);
48	
49	  const joystickLocal = (e: React.PointerEvent) => ({
50	    pointerId: e.pointerId,
51	    x: e.clientX - joystickCenter.current.x,
52	    y: e.clientY - joystickCenter.current.y
53	  });
54	
55	  const onJoystickDown = (e: React.PointerEvent) => {
56	    capture(e);
57	    const rect = e.currentTarget.getBoundingClientRect();
58	    joystickCenter.current = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
59	    const p = joystickLocal(e);
60	    controls.joystickDown(p);
61	    setKnob(clampKnob(p.x, p.y));
62	  };
63	  const onJoystickMove = (e: React.PointerEvent) => {
64	    const p = joystickLocal(e);
65	    controls.joystickMove(p);
66	    setKnob(clampKnob(p.x, p.y));
67	  };
68	  const onJoystickEnd = (e: React.PointerEvent) => {
69	    controls.joystickUp(e.pointerId);
70	    setKnob({ x: 0, y: 0 });
71	  };
72	
73	  const lookPoint = (e: React.PointerEvent) => ({ pointerId: e.pointerId, x: e.clientX, y: e.clientY });
74	
75	  return (
76	    <>
77	      <div
78	        className="touch-lookpad"
79	        data-testid="touch-lookpad"
80	        onPointerDown={(e) => {
81	          capture(e);
82	          controls.lookDown(lookPoint(e));
83	        }}
84	        onPointerMove={(e) => controls.lookMove(lookPoint(e))}
85	        onPointerUp={(e) => controls.lookUp(e.pointerId)}
86	        onPointerCancel={(e) => controls.lookCancel(e.pointerId)}
87	      />
88	
89	      <div
90	        className="touch-joystick"
91	        data-testid="touch-joystick"
92	        onPointerDown={onJoystickDown}
93	        onPointerMove={onJoystickMove}
94	        onPointerUp={onJoystickEnd}
95	        onPointerCancel={onJoystickEnd}
96	      >
97	        <div className="touch-joystick-knob" style={{ transform: `translate(${knob.x}px, ${knob.y}px)` }} aria-hidden="true" />
98	      </div>
99	
100	      <div className="touch-actions">
101	        {showEat ? (
102	          <button
103	            type="button"
104	            className="touch-btn"
105	            data-testid="touch-eat"
106	            onPointerDown={() => controls.buttonDown("eat")}
107	            onPointerUp={() => controls.buttonUp("eat")}
108	          >
109	            Eat
110	          </button>
111	        ) : null}
112	        <button
113	          type="button"
114	          className="touch-btn"
115	          data-testid="touch-place"
116	          onPointerDown={() => controls.buttonDown("place")}
117	          onPointerUp={() => controls.buttonUp("place")}
118	        >
119	          Place
120	        </button>
121	        <button
122	          type="button"
123	          className={sneakOn ? "touch-btn pressed" : "touch-btn"}
124	          data-testid="touch-sneak"
125	          aria-pressed={sneakOn}
126	          onPointerDown={() => {
127	            controls.buttonDown("sneak");
128	            setSneakOn(controls.sneakLatched);
129	          }}
130	          onPointerUp={() => controls.buttonUp("sneak")}
131	        >
132	          {isFlying ? "Descend" : "Sneak"}
133	        </button>
134	        <button
135	          type="button"
136	          className="touch-btn touch-btn-jump"
137	          data-testid="touch-jump"
138	          onPointerDown={() => controls.buttonDown("jump")}
139	          onPointerUp={() => controls.buttonUp("jump")}
140	          onPointerCancel={() => controls.buttonUp("jump")}
141	        >
142	          {isFlying ? "Rise" : "Jump"}
143	        </button>
144	      </div>
145	
146	      <div className="touch-topbar">
147	        <button type="button" className="touch-btn" data-testid="touch-pause" onPointerDown={onPause}>
148	          ❚❚
149	        </button>
150	        <button type="button" className="touch-btn" data-testid="touch-inventory" onPointerDown={onOpenInventory}>
151	          Items
152	        </button>
153	        <button type="button" className="touch-btn" data-testid="touch-camera" onPointerDown={onToggleCamera}>
154	          View
155	        </button>
156	      </div>
157	    </>
158	  );
159	}
160	
161	function clampKnob(x: number, y: number): { x: number; y: number } {
162	  const len = Math.hypot(x, y);
163	  if (len <= TOUCH_JOYSTICK_RADIUS_PX) return { x, y };
164	  const scale = TOUCH_JOYSTICK_RADIUS_PX / len;
165	  return { x: x * scale, y: y * scale };
166	}

