export default function PauseMenu({
  saveMessage,
  audioSettings,
  onAudioSettingsChange,
  gameMode,
  onGameModeChange,
  difficulty,
  onDifficultyChange,
  hardcore,
  skinId,
  onSkinChange,
  touchMode,
  onTouchModeChange,
  touchActive,
  onUnstuck,
  onBack,
  onSave,
  onLoad,
  onReset,
