6	import type { GameMode } from "@/lib/game/gameModes";
7	import type { Difficulty } from "@/lib/game/difficulties";
8	import { DEFAULT_SKIN_ID, SKIN_PRESETS } from "@/lib/game/playerSkins";
9	
10	function renderMenu(overrides: Partial<Parameters<typeof PauseMenu>[0]> = {}) {
11	  const props = {
12	    saveMessage: "",
13	    audioSettings: DEFAULT_AUDIO_SETTINGS,
14	    onAudioSettingsChange: mock(),
15	    gameMode: "survival" as GameMode,
16	    onGameModeChange: mock(),
17	    difficulty: "normal" as Difficulty,
18	    onDifficultyChange: mock(),
19	    hardcore: false,
20	    skinId: DEFAULT_SKIN_ID,
21	    onSkinChange: mock(),
22	    onBack: mock(),
23	    onSave: mock(),
24	    onLoad: mock(),
25	    onReset: mock(),
26	    onQuitToWorlds: mock(),
27	    ...overrides
28	  };
29	  render(<PauseMenu {...props} />);
30	  return props;
31	}
32	
33	describe("PauseMenu", () => {
34	  test("buttons dispatch their callbacks", async () => {
35	    const user = userEvent.setup();
36	    const props = renderMenu();
37	    await user.click(screen.getByRole("button", { name: "Back to Game" }));
38	    await user.click(screen.getByRole("button", { name: "Save Game" }));
39	    await user.click(screen.getByRole("button", { name: "Load Save" }));
40	    await user.click(screen.getByRole("button", { name: "Save & Quit to Worlds" }));
41	    expect(props.onBack).toHaveBeenCalledTimes(1);
42	    expect(props.onSave).toHaveBeenCalledTimes(1);
43	    expect(props.onLoad).toHaveBeenCalledTimes(1);
44	    expect(props.onQuitToWorlds).toHaveBeenCalledTimes(1);
45	  });
46	
47	  test("reset requires a confirmation step", async () => {
48	    const user = userEvent.setup();
49	    const props = renderMenu();
50	    await user.click(screen.getByRole("button", { name: "Reset World" }));
51	    expect(props.onReset).not.toHaveBeenCalled();
52	    await user.click(screen.getByRole("button", { name: "Confirm Reset" }));
53	    expect(props.onReset).toHaveBeenCalledTimes(1);
54	  });
55	
56	  test("cancel backs out of the reset confirmation", async () => {
57	    const user = userEvent.setup();
58	    const props = renderMenu();
59	    await user.click(screen.getByRole("button", { name: "Reset World" }));
